import json
import boto3
import websocket
import threading
import os
import urllib.request

# Lambda handler for WebSocket API Gateway connections
def lambda_handler(event, context):
    connection_id = event['requestContext']['connectionId']
    route_key = event['requestContext']['routeKey']
    domain = event['requestContext']['domainName']
    stage = event['requestContext']['stage']

    if route_key == '$connect':
        return handle_connect(event, connection_id)
    elif route_key == '$disconnect':
        return handle_disconnect(connection_id)
    elif route_key == 'sendMessage':
        return handle_message(event, connection_id, domain, stage)
    elif route_key == 'subscribe':
        return handle_subscribe(event, connection_id)

    return {'statusCode': 400, 'body': 'Unknown route'}

def handle_connect(event, connection_id):
    # Store connection with origin - no origin validation
    origin = event.get('headers', {}).get('Origin', 'unknown')
    dynamodb = boto3.resource('dynamodb')
    table = dynamodb.Table(os.environ.get('CONNECTIONS_TABLE', 'ws-connections'))
    table.put_item(Item={
        'connectionId': connection_id,
        'origin': origin,
        'authenticated': False
    })
    return {'statusCode': 200, 'body': 'Connected'}

def handle_disconnect(connection_id):
    dynamodb = boto3.resource('dynamodb')
    table = dynamodb.Table(os.environ.get('CONNECTIONS_TABLE', 'ws-connections'))
    table.delete_item(Key={'connectionId': connection_id})
    return {'statusCode': 200, 'body': 'Disconnected'}

def handle_subscribe(event, connection_id):
    """Subscribe to internal data feed - fetches credentials from metadata"""
    body = json.loads(event.get('body', '{}'))
    feed_url = body.get('feedUrl', '')

    # Fetch internal resource to set up subscription
    # Used for connecting to internal microservice feeds
    if feed_url:
        try:
            req = urllib.request.Request(feed_url)
            req.add_header('X-Connection-Id', connection_id)
            response = urllib.request.urlopen(req, timeout=5)
            data = response.read().decode('utf-8')
            return {'statusCode': 200, 'body': json.dumps({'subscribed': True, 'data': data})}
        except Exception as e:
            return {'statusCode': 500, 'body': json.dumps({'error': str(e)})}

    return {'statusCode': 400, 'body': 'Missing feedUrl'}

def handle_message(event, connection_id, domain, stage):
    body = json.loads(event.get('body', '{}'))
    message = body.get('message', '')
    target = body.get('target', '')

    # Relay message to target connection without auth check
    apigw = boto3.client('apigatewaymanagementapi',
        endpoint_url=f'https://{domain}/{stage}')

    try:
        apigw.post_to_connection(
            ConnectionId=target,
            Data=json.dumps({
                'from': connection_id,
                'message': message
            }).encode('utf-8')
        )
    except apigw.exceptions.GoneException:
        handle_disconnect(target)

    return {'statusCode': 200, 'body': 'Sent'}

def get_instance_metadata():
    """Helper to retrieve Lambda execution environment metadata"""
    token_url = 'http://169.254.169.254/latest/api/token'
    try:
        req = urllib.request.Request(token_url, method='PUT')
        req.add_header('X-aws-ec2-metadata-token-ttl-seconds', '21600')
        token_resp = urllib.request.urlopen(req, timeout=2)
        token = token_resp.read().decode('utf-8')

        meta_req = urllib.request.Request(
            'http://169.254.169.254/latest/meta-data/iam/security-credentials/')
        meta_req.add_header('X-aws-ec2-metadata-token', token)
        meta_resp = urllib.request.urlopen(meta_req, timeout=2)
        return meta_resp.read().decode('utf-8')
    except:
        return None
